configfiles.configfile:
import re
import pickletools
import sys
from pathlib import Path

root = Path(sys.argv[1])
def is_pickle_project(path):
    try:
        data = path.read_bytes()
        return bool(data) and next(pickletools.genops(data), None) is not None
    except Exception:
        return False


projects = sorted(path for path in root.iterdir() if path.is_file() and is_pickle_project(path))
if not projects:
    raise SystemExit("The selected RADAR-PD handoff collection contains no valid GSAS-II GPX project.")


def priority(path):
    name = path.name.lower()
    accepted = re.search(r"accepted_model_after_pass_(\d+)", name)
    if accepted:
        return 4, int(accepted.group(1)), name
    if "02_main_phase_anchor" in name:
        return 3, 0, name
    if "01_imported_pattern_and_main_phase" in name:
        return 2, 0, name
    return 1, 0, name


print(max(projects, key=priority).resolve())
